experiments/04_branch_divergence.hip<pre><code>#include "common.h"

constexpr int BRANCH_ITERS = 4096;

template &lt;int MODE&gt;
__global__ void branch_divergence_kernel(const float* __restrict__ in,
                                         float* __restrict__ out,
                                         int n) {
    int gid = blockIdx.x * blockDim.x + threadIdx.x;
    if (gid &gt;= n) return;

    float x = in[gid];
    float y = 1.0001f;

    for (int i = 0; i &lt; BRANCH_ITERS; ++i) {
        if constexpr (MODE == 0) {
            // 基准：无分支
            x = x * 1.00001f + y;
        } else if constexpr (MODE == 1) {
            // Wave-uniform 分支设计：按 Wavefront 编号分奇偶
            if (((threadIdx.x / warpSize) &amp; 1) == 0) {
                x = x * 1.00001f + y;
            } else {
                x = x * 0.99999f - y;
            }
        } else if constexpr (MODE == 2) {
            // 2-way Lane-divergent：同一 Wave 内奇偶 Lane 分叉
            if ((threadIdx.x &amp; 1) == 0) {
                x = x * 1.00001f + y;
            } else {
                x = x * 0.99999f - y;
            }
        } else if constexpr (MODE == 3) {
            // 4-way Lane-divergent：同一 Wave 内 4 路分叉
            int lane_mod = threadIdx.x &amp; 3;
            if (lane_mod == 0) {
                x = x * 1.00001f + y;
            } else if (lane_mod == 1) {
                x = x * 0.99999f - y;
            } else if (lane_mod == 2) {
                x = x * 1.00002f + y * 0.5f;
            } else {
                x = x * 0.99998f - y * 0.5f;
            }
        }
    }
    out[gid] = x;
}
</code></pre>

experiments/05_occupancy_and_ilp.hip<pre><code>#include "common.h"

// Low-ILP：单路串行依赖加载（高度依赖 TLP / 高 Occupancy 隐藏延迟）
__global__ void low_ilp_kernel(const float* __restrict__ a,
                               float* __restrict__ out,
                               int n,
                               int steps) {
    extern __shared__ char dummy_lds[];
    int gid = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = gridDim.x * blockDim.x;
    if (gid &gt;= n) return;

    float acc = 0.0f;
    int idx = gid;
    for (int s = 0; s &lt; steps; ++s) {
        acc += a[idx];
        idx += stride;
        if (idx &gt;= n) idx -= n;
    }
    if (threadIdx.x == 0 &amp;&amp; dummy_lds[0] == 123) out[0] = 0.0f; // 防止动态 LDS 被优化掉
    out[gid] = acc;
}

// High-ILP：每轮发射 4 条独立加载（在低 Occupancy 下靠单 Wave 内 ILP 抗延迟）
__global__ void high_ilp_kernel(const float* __restrict__ a,
                                float* __restrict__ out,
                                int n,
                                int steps) {
    extern __shared__ char dummy_lds[];
    int gid = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = gridDim.x * blockDim.x;
    if (gid &gt;= n) return;

    float acc0 = 0.0f, acc1 = 0.0f, acc2 = 0.0f, acc3 = 0.0f;
    int idx0 = gid;
    int idx1 = (gid + stride) % n;
    int idx2 = (gid + 2 * stride) % n;
    int idx3 = (gid + 3 * stride) % n;

    for (int s = 0; s &lt; steps; s += 4) {
        float v0 = a[idx0];
        float v1 = a[idx1];
        float v2 = a[idx2];
        float v3 = a[idx3];
        acc0 += v0; acc1 += v1; acc2 += v2; acc3 += v3;
        idx0 = (idx0 + 4 * stride) % n;
        idx1 = (idx1 + 4 * stride) % n;
        idx2 = (idx2 + 4 * stride) % n;
        idx3 = (idx3 + 4 * stride) % n;
    }
    if (threadIdx.x == 0 &amp;&amp; dummy_lds[0] == 123) out[0] = 0.0f;
    out[gid] = (acc0 + acc1) + (acc2 + acc3);
}
