experiments/06_shuffle_vs_lds.hip<pre><code>#include "common.h"
#include &lt;vector&gt;

constexpr int BLOCK_SIZE = 256;

// 方式 A：纯 LDS 树状规约（需要 8 次 __syncthreads()）
__global__ void reduce_lds_kernel(const float* __restrict__ in,
                                  float* __restrict__ out,
                                  int cols) {
    __shared__ float sdata[BLOCK_SIZE];
    int row = blockIdx.x;
    int tid = threadIdx.x;

    float sum = 0.0f;
    for (int c = tid; c &lt; cols; c += BLOCK_SIZE) {
        sum += in[row * cols + c];
    }
    sdata[tid] = sum;
    __syncthreads();

    for (int offset = BLOCK_SIZE / 2; offset &gt; 0; offset &gt;&gt;= 1) {
        if (tid &lt; offset) {
            sdata[tid] += sdata[tid + offset];
        }
        __syncthreads();
    }
    if (tid == 0) out[row] = sdata[0];
}

// 方式 B：Wave 内 __shfl_down 寄存器规约 + 仅 1 次 LDS 汇总
__global__ void reduce_shuffle_kernel(const float* __restrict__ in,
                                      float* __restrict__ out,
                                      int cols) {
    __shared__ float wave_sums[8]; // 兼容 Wave64 (4 waves) 与 Wave32 (8 waves)
    int row = blockIdx.x;
    int tid = threadIdx.x;
    int lane = tid % warpSize;
    int wave_id = tid / warpSize;
    int num_waves = BLOCK_SIZE / warpSize;

    float sum = 0.0f;
    for (int c = tid; c &lt; cols; c += BLOCK_SIZE) {
        sum += in[row * cols + c];
    }

    // 1. Wave 内寄存器级规约（无 LDS、无 Barrier）
    for (int offset = warpSize / 2; offset &gt; 0; offset &gt;&gt;= 1) {
        sum += __shfl_down(sum, offset);
    }

    // 2. 仅每个 Wave 的 Lane 0 写入 LDS
    if (lane == 0) wave_sums[wave_id] = sum;
    __syncthreads();

    // 3. Wave 0 汇总全部 Wave 的部分和
    if (wave_id == 0) {
        float final_sum = (lane &lt; num_waves) ? wave_sums[lane] : 0.0f;
        for (int offset = warpSize / 2; offset &gt; 0; offset &gt;&gt;= 1) {
            final_sum += __shfl_down(final_sum, offset);
        }
        if (lane == 0) out[row] = final_sum;
    }
}
</code></pre>

experiments/07_memory_latency_ladder.hip<pre><code>#include "common.h"
#include &lt;vector&gt;
#include &lt;numeric&gt;
#include &lt;algorithm&gt;
#include &lt;random&gt;

// 1. 全局内存指针追逐：只派 1 个线程，消除并发隐藏，暴露最纯粹的往返延迟
__global__ void global_chase_kernel(const int* __restrict__ next_idx,
                                    int* __restrict__ out,
                                    unsigned long long* __restrict__ out_cycles,
                                    int steps) {
    int idx = 0;
    // 先预热一轮：让小工作集的数据提前住进 L1 / L2 Cache
    for (int i = 0; i &lt; steps; ++i) {
        idx = next_idx[idx];
    }

    // 用 GPU 硬件时钟 clock64() 记录纯粹的追逐周期数
    unsigned long long t0 = clock64();
    for (int i = 0; i &lt; steps; ++i) {
        idx = next_idx[idx];
    }
    unsigned long long t1 = clock64();

    out[0] = idx;
    out_cycles[0] = t1 - t0;
}

// 2. LDS 指针追逐：对比片上共享内存的延迟
__global__ void lds_chase_kernel(int* __restrict__ out,
                                 unsigned long long* __restrict__ out_cycles,
                                 int n_elems,
                                 int steps) {
    __shared__ int s_next[4096]; // 16 KB LDS
    for (int i = 0; i &lt; n_elems; ++i) {
        s_next[i] = (i + 17) % n_elems; // 互质步长构建环形链
    }
    __syncthreads();

    int idx = 0;
    for (int i = 0; i &lt; steps; ++i) idx = s_next[idx];
    unsigned long long t0 = clock64();
    for (int i = 0; i &lt; steps; ++i) idx = s_next[idx];
    unsigned long long t1 = clock64();

    out[0] = idx;
    out_cycles[0] = t1 - t0;
}
</code></pre>

experiments/08_mmac_builtin_bench.hip<pre><code>#include "common.h"

// 定义 LLVM 向量类型：对应 AMDGCN 中的连续 VGPR 寄存器组
using float4_t = float __attribute__((ext_vector_type(4)));
using half4_t = _Float16 __attribute__((ext_vector_type(4)));

constexpr int ITERS = 4096;

// 1. VALU FP32 峰值测试：每线程开 8 路互不依赖的累加器，打满向量流水线
__global__ void valu_fp32_peak_kernel(float* __restrict__ out, float seed) {
    float a0 = seed + 0.1f, a1 = seed + 0.2f, a2 = seed + 0.3f, a3 = seed + 0.4f;
    float a4 = seed + 0.5f, a5 = seed + 0.6f, a6 = seed + 0.7f, a7 = seed + 0.8f;
    float b = 1.0001f, c = 0.0001f;

    for (int i = 0; i &lt; ITERS; ++i) {
        a0 = a0 * b + c; a1 = a1 * b + c; a2 = a2 * b + c; a3 = a3 * b + c;
        a4 = a4 * b + c; a5 = a5 * b + c; a6 = a6 * b + c; a7 = a7 * b + c;
    }
    int gid = blockIdx.x * blockDim.x + threadIdx.x;
    out[gid] = (a0 + a1 + a2 + a3) + (a4 + a5 + a6 + a7);
}

// 2. HCU Builtin MMAC 峰值测试：每 Wave 开 8 路独立的 16x16x16 矩阵累加器
__global__ void mmac_fp16_peak_kernel(float* __restrict__ out, _Float16 seed) {
    half4_t a = {seed, seed, seed, seed};
    half4_t b = {(_Float16)1.0, (_Float16)1.0, (_Float16)1.0, (_Float16)1.0};
    float4_t c0 = {0, 0, 0, 0}, c1 = {0, 0, 0, 0}, c2 = {0, 0, 0, 0}, c3 = {0, 0, 0, 0};
    float4_t c4 = {0, 0, 0, 0}, c5 = {0, 0, 0, 0}, c6 = {0, 0, 0, 0}, c7 = {0, 0, 0, 0};

    for (int i = 0; i &lt; ITERS; ++i) {
        c0 = __builtin_hcu_mmac_f32_16x16x16_f16(a, b, c0);
        c1 = __builtin_hcu_mmac_f32_16x16x16_f16(a, b, c1);
        c2 = __builtin_hcu_mmac_f32_16x16x16_f16(a, b, c2);
        c3 = __builtin_hcu_mmac_f32_16x16x16_f16(a, b, c3);
        c4 = __builtin_hcu_mmac_f32_16x16x16_f16(a, b, c4);
        c5 = __builtin_hcu_mmac_f32_16x16x16_f16(a, b, c5);
        c6 = __builtin_hcu_mmac_f32_16x16x16_f16(a, b, c6);
        c7 = __builtin_hcu_mmac_f32_16x16x16_f16(a, b, c7);
    }
    int gid = blockIdx.x * blockDim.x + threadIdx.x;
    float4_t s = (c0 + c1 + c2 + c3) + (c4 + c5 + c6 + c7);
    out[gid] = s[0] + s[1] + s[2] + s[3];
}

// 3. 单条 MMAC 依赖延迟测试：仅用 1 路累加器 c，逼迫硬件等上一条算完才能算下一条
__global__ void mmac_fp16_latency_kernel(float* __restrict__ out,
                                         unsigned long long* __restrict__ out_cycles,
                                         _Float16 seed) {
    half4_t a = {seed, seed, seed, seed};
    half4_t b = {(_Float16)1.0, (_Float16)1.0, (_Float16)1.0, (_Float16)1.0};
    float4_t c = {0, 0, 0, 0};

    unsigned long long t0 = clock64();
    for (int i = 0; i &lt; ITERS; ++i) {
        c = __builtin_hcu_mmac_f32_16x16x16_f16(a, b, c);
    }
    unsigned long long t1 = clock64();
    if (threadIdx.x == 0) {
        out[0] = c[0];
        out_cycles[0] = t1 - t0;
    }
}
</code></pre>
